function UIThirdConfirmPopUp:__init()
    ---@type fun():void
    self.confirmCB = nil
    ---@type fun():void
    self.cancelCB = nil
    self._itemLoader = nil
end

function UIThirdConfirmPopUp:__delete()
    self.confirmCB = nil
