function UIThirdConfirmPopUp:Awake()
    self.controller.ClearCache = false
    SetButtonAction(self.BtnOk, function()
        if self.confirmCB ~= nil and type(self.confirmCB) == 'function' then
            if not isNull(self.confirmCB) then
                KTool.SafeDelete(self.controller.gameObject)
                self.confirmCB()
            end
        else
            KTool.SafeDelete(self.controller.gameObject)
        end
    end)

    SetButtonAction(self.BtnCancel, function()
        if self.cancelCB ~= nil and type(self.cancelCB) == 'function' then
            if self.cancelCB() then
                KTool.SafeDelete(self.controller.gameObject)
            end
        else
            KTool.SafeDelete(self.controller.gameObject)
        end
    end)
end

