function UIThirdConfirmPopUp:ShowHUD(titleContent, okCB, cancelCB, rewards)
    CfUtils.FillText(self.title, titleContent)
    self.confirmCB = okCB
    self.cancelCB = cancelCB

    self:FillRewards(rewards)
end

--绘制奖励
function UIThirdConfirmPopUp:FillRewards(rewards)
    if not rewards then
        return
    end
    local rewrdArr = {}
    for k, v in pairs(rewards) do
        table.insert(rewrdArr, v)
    end

    for i = 1, #rewrdArr do
        local go = self.rewards.transform:Find("reward"..i)
        if not go then
            go = CfUtils.InstantiateGo(self.reward, self.rewards)
            go.name = "reward"..i
        end
        self:FillReward(go, rewrdArr[i])
    end
end

function UIThirdConfirmPopUp:FillReward(goPar, data)
    if not goPar or not data then
        return
    end
    if checkNumber(data.num) <= 0 then
        return
    end

    if not self._itemLoader then
        self._itemLoader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
    end
    if self._itemLoader.IsSuccess then
        local go = goPar.transform:Find("item")
        if not go then 
            go = CfUtils.InstantiateGo(self._itemLoader.ResultObject, goPar.transform:Find("item"))
            go.name = "item"
        end
        if go then
            CfUtils.RefeshGoodGo(go, data.goodsId, data.num, 0.82, nil, nil, data.playerItemId)
        end
    end

    KTool.SetActive(goPar, true)
end

function UIThirdConfirmPopUp:OnDestroy()
    if not isNull(self._itemLoader) then
        self._itemLoader:Release()
        self._itemLoader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIThirdConfirmPopUp